    def __init__(self, a, b=0.0):
        self.a, self.b = float(a), float(b)   # parte real e infinitesimal
    def __add__(self, o):
        o = o if isinstance(o, Dual) else Dual(o)
        return Dual(self.a + o.a, self.b + o.b)
